        "script": "const email = $vars.emailReceived1.output;
const subject = (email.subject || '').toLowerCase();
const bodyText = (email.bodyPreview || '').toLowerCase();
const fromAddress = (email.from && email.from.emailAddress ? email.from.emailAddress.address : '').toLowerCase();
const text = subject + ' ' + bodyText;

const vipPatterns = ['enterprise-customer.com', 'bigclient.com', 'vip@example.com', 'ceo@', 'director@', 'vp@'];
const isVIP = vipPatterns.some(function(p) { return fromAddress.indexOf(p) !== -1; });

const urgentKeywords = ['urgent', 'critical', 'outage', 'down', 'asap', 'emergency', 'escalate', 'not working', 'failed', 'failure', 'immediately', 'refund', 'legal', 'lawsuit', 'complaint', 'angry', 'furious', 'unacceptable'];
const hasUrgent = urgentKeywords.some(function(k) { return text.indexOf(k) !== -1; });

var score = 0;
if (isVIP) score += 2;
if (hasUrgent) score += 1;

var urgencyLevel = score >= 2 ? 'Critical' : (score === 1 ? 'Priority' : 'Standard');
var vipTag = isVIP ? ' [VIP]' : '';
var priorityTag = '[' + urgencyLevel.toUpperCase() + vipTag + ']';

return { urgencyLevel: urgencyLevel, isVIP: isVIP, priorityTag: priorityTag };"

